// module app
internal fun foo() = "secret"

// compiles to (bytecode): public final foo$app()
// Java caller:  foo$app()  — works fine, no compile error

// test source set is a friend module:
class AppTest { @Test fun t() { foo() } }   // OK — sees internal

// Kotlin protected = subclass only (no package tier):
open class A { protected fun p() {} }
// class B { fun q(a: A) { a.p() } }  // ERROR — not a subclass

class PrefDelegate(private val prefs: SharedPreferences)
    : ReadWriteProperty<Any?, String> {
    override fun getValue(r: Any?, p: KProperty<*>) = prefs.getString(p.name, "") ?: ""
    override fun setValue(r: Any?, p: KProperty<*>, v: String) =
        prefs.edit().putString(p.name, v).apply()
}

var token: String by PrefDelegate(prefs)   // key = "token"

var count by Delegates.observable(0) { _, _, new -> save(new) }
var age by Delegates.vetoable(0) { _, _, new -> new in 0..150 }
var db by Delegates.notNull<Database>()
val j: Int by mapOf("j" to 42)

interface Repo {
    fun get(key: String): String
    fun getAll(): List<String>       // internally calls get()
}

class BaseRepo : Repo {
    override fun get(key: String) = "base:$key"
    override fun getAll() = listOf(get("a"), get("b"))  // calls BaseRepo.get
}

class CacheRepo(private val inner: Repo) : Repo by inner {
    override fun get(key: String): String {
        println("CACHE $key")
        return inner.get(key)
    }
}

// repo.getAll() -> BaseRepo.get — the CACHE line never prints.

// Capturing lambda: allocates per call site evaluation
fun makeCounter(): () -> Int {
    var count = 0                       // boxed into Ref.IntRef on the heap
    return { ++count }                  // captures the Ref
}

// Listener leak: lambda captures this@Activity strongly
class MainActivity : AppCompatActivity() {
    override fun onCreate(b: Bundle?) {
        viewModel.button.setOnClickListener { load() }  // retains this
    }
}

// Bound reference allocates; top-level reference is cached
val ref = this::load                // allocates per evaluation
val ref2 = ::topLevel              // cached singleton
